    def sgn(x):
        return -1 if x < 0 else (1 if x > 0 else 0)

    def man(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    def step_toward(a, b):
        return [sgn(b[0] - a[0]), sgn(b[1] - a[1])]

    def clip_move(d):
        return [0 if d[0] == 0 else (1 if d[0] > 0 else -1),
                0 if d[1] == 0 else (1 if d[1] > 0 else -1)]

    def parse_positions(v):
